import { app, shell, BrowserWindow, ipcMain, dialog } from 'electron'
import { join } from 'path'
import * as fs from 'fs'
import { electronApp, optimizer, is } from '@electron-toolkit/utils'
import icon from '../../resources/icon.png?asset'
import { Scanner } from './scanner'

let mainWindow: BrowserWindow | null = null;
let scanner: Scanner | null = null;

function createWindow(): void {
  // Create the browser window.
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    minWidth: 900,
    minHeight: 600,
    show: false,
    autoHideMenuBar: true,
    ...(process.platform === 'linux' ? { icon } : {}),
    webPreferences: {
      preload: join(__dirname, '../preload/index.js'),
      sandbox: false
    }
  })

  mainWindow.on('ready-to-show', () => {
    mainWindow?.show()
  })

  mainWindow.webContents.setWindowOpenHandler((details) => {
    shell.openExternal(details.url)
    return { action: 'deny' }
  })

  // HMR for renderer base on electron-vite cli.
  // Load the remote URL for development or the local html file for production.
  if (is.dev && process.env['ELECTRON_RENDERER_URL']) {
    mainWindow.loadURL(process.env['ELECTRON_RENDERER_URL'])
  } else {
    mainWindow.loadFile(join(__dirname, '../renderer/index.html'))
  }
}

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
app.whenReady().then(() => {
  electronApp.setAppUserModelId('com.electron')

  app.on('browser-window-created', (_, window) => {
    optimizer.watchWindowShortcuts(window)
  })

  createWindow()

  app.on('activate', function () {
    if (BrowserWindow.getAllWindows().length === 0) createWindow()
  })

  // Initialize Scanner Service
  scanner = new Scanner();
})

// Quit when all windows are closed, except on macOS.
app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit()
  }
})

// IPC Handlers
ipcMain.handle('select-directory', async () => {
  if (!mainWindow) return null;
  const result = await dialog.showOpenDialog(mainWindow, {
    properties: ['openDirectory']
  });
  return result.canceled ? null : result.filePaths[0];
});

ipcMain.handle('check-model-status', async () => {
  return { ready: scanner ? scanner.isModelReady() : false };
});

ipcMain.handle('start-scan', async (event, dirPath) => {
  if (!scanner) return [];

  // Send progress events back to the renderer
  const onProgress = (progress: number, newVuln: any) => {
    event.sender.send('scan-progress', progress, newVuln);
  };

  try {
    const results = await scanner.scanDirectory(dirPath, onProgress);
    return results;
  } catch (error) {
    console.error('Scan failed:', error);
    return [];
  }
});

ipcMain.handle('export-pdf', async () => {
  if (!mainWindow) return { success: false, error: 'No main window' };

  try {
    const pdfData = await mainWindow.webContents.printToPDF({
      printBackground: true,
      landscape: false
    });

    const { canceled, filePath } = await dialog.showSaveDialog(mainWindow, {
      title: 'Save Vulnerability Report',
      defaultPath: 'ODAVA_Report.pdf',
      filters: [{ name: 'PDF', extensions: ['pdf'] }]
    });

    if (!canceled && filePath) {
      fs.writeFileSync(filePath, pdfData);
      return { success: true, filePath };
    }
    return { success: false, canceled: true };
  } catch (error: any) {
    console.error('Failed to export PDF:', error);
    return { success: false, error: error.message };
  }
});

import * as fs from 'fs';
import * as path from 'path';
import { app } from 'electron';
import { AiService } from './ai-service';
import { SecurityRuleEngine, RuleResult } from './security-rules';

export class Scanner {
  private aiService: AiService;

  private supportedExtensions = [
    '.js', '.ts', '.jsx', '.tsx', '.py', '.java', '.go', '.php',
    '.c', '.cpp', '.cs', '.html', '.vue', '.sql', '.sh', '.json',
    '.yml', '.yaml', '.env'
  ];

  private ignoreDirs = [
    'node_modules', '.git', 'dist', 'build', 'out', '.next', '.nuxt',
    'coverage', 'vendor', '__pycache__', '.idea', '.vscode'
  ];

  constructor() {
    this.aiService = new AiService();
    const modelPath = app.isPackaged 
      ? path.join(process.resourcesPath, 'models', 'qwen2.5-0.5b-instruct-q4_k_m.gguf')
      : path.join(process.cwd(), 'models', 'qwen2.5-0.5b-instruct-q4_k_m.gguf');

    this.aiService.init(modelPath).catch(console.error);
  }

  public isModelReady(): boolean {
    return this.aiService.isReady;
  }

  async scanDirectory(dirPath: string, onProgress: (progress: number, newVuln: any | null) => void): Promise<any[]> {
    const filesToScan: string[] = [];
    this.walkDir(dirPath, filesToScan);

    const vulnerabilities: any[] = [];
    const totalFiles = filesToScan.length;

    if (totalFiles === 0) {
      onProgress(100, null);
      return vulnerabilities;
    }

    for (let i = 0; i < totalFiles; i++) {
      const file = filesToScan[i];
      const relativePath = path.relative(dirPath, file);
      const ext = path.extname(file).toLowerCase();

      try {
        const content = fs.readFileSync(file, 'utf-8');
        const ruleResults: RuleResult[] = SecurityRuleEngine.analyzeSnippet(content, file.endsWith('.env') ? '.env' : ext);

        if (ruleResults.length > 0) {
          for (let res of ruleResults) {
            let enriched: any = { ...res };
            let isFalsePositive = false;
            let confidence = "low";

            if (this.aiService.isReady) {
              const aiEnriched = await this.aiService.enrichRuleResult(relativePath, res);
              enriched = aiEnriched;
              isFalsePositive = aiEnriched.isFalsePositive;
              confidence = aiEnriched.confidence;
            }

            if (!isFalsePositive) {
              const vulnObj = {
                id: Math.random().toString(36).substring(2, 11),
                file: relativePath,
                title: enriched.title,
                severity: enriched.severity,
                description: enriched.description,
                snippet: enriched.snippet,
                recommendation: enriched.recommendation,
                cwe: enriched.cwe,
                confidence: confidence
              };

              vulnerabilities.push(vulnObj);
              onProgress(Math.floor(((i + 1) / totalFiles) * 100), vulnObj);
            }
          }
        }

        // Report progress step
        onProgress(Math.floor(((i + 1) / totalFiles) * 100), null);
      } catch (err) {
        console.error(`Error reading file ${file}`, err);
        onProgress(Math.floor(((i + 1) / totalFiles) * 100), null);
      }
    }

    onProgress(100, null);
    return vulnerabilities;
  }

  private walkDir(dir: string, fileList: string[]) {
    try {
      const files = fs.readdirSync(dir);
      for (const file of files) {
        if (this.ignoreDirs.includes(file) || file.startsWith('.') && !file.endsWith('.env')) continue;

        const filePath = path.join(dir, file);
        const stat = fs.statSync(filePath);

        if (stat.isDirectory()) {
          this.walkDir(filePath, fileList);
        } else {
          const ext = path.extname(file).toLowerCase();
          if ((this.supportedExtensions.includes(ext) || file.endsWith('.env')) && stat.size < 500000) {
            fileList.push(filePath);
          }
        }
      }
    } catch (err) {
      console.error(`Error walking directory ${dir}`, err);
    }
  }
}

import * as fs from 'fs';
import { RuleResult } from './security-rules';
import findingSchema from './data/finding-schema.json';
import enrichmentPrompts from './data/enrichment-prompts.json';

export interface EnrichedFinding {
  description: string;
  remediation: string;
  isFalsePositive: boolean;
  confidence: "low" | "medium" | "high";
}

export class AiService {
  private llama: any | null = null;
  private model: any | null = null;
  private context: any | null = null;
  private session: any | null = null;
  private grammar: any | null = null;

  public isReady = false;

  async init(modelPath?: string) {
    try {
      const { getLlama, LlamaChatSession } = await import('node-llama-cpp');

      this.llama = await getLlama();

      if (modelPath && fs.existsSync(modelPath)) {
        this.model = await this.llama.loadModel({
          modelPath: modelPath
        });
        this.context = await this.model.createContext();
        this.session = new LlamaChatSession({
          contextSequence: this.context.getSequence()
        });
        this.grammar = await this.llama.createGrammarForJsonSchema(findingSchema as any);
        this.isReady = true;
      }
    } catch (e) {
      console.error('Failed to initialize AI Service', e);
      this.isReady = false;
    }
  }

  async enrichRuleResult(filename: string, ruleResult: RuleResult): Promise<RuleResult & EnrichedFinding> {
    const fallback: RuleResult & EnrichedFinding = {
      ...ruleResult,
      isFalsePositive: false,
      confidence: "low",
      remediation: ""
    };

    if (!this.session || !this.isReady || !this.grammar) {
      return fallback;
    }

    try {
      const cweEntry = (enrichmentPrompts.perCwe as Record<string, any>)[ruleResult.cwe];

      const system = enrichmentPrompts.basePromptTemplate
        .replace("{{CWE_ID}}", ruleResult.cwe)
        .replace("{{CWE_NAME}}", cweEntry?.name ?? "Security Weakness")
        .replace("{{RULE_MESSAGE}}", ruleResult.description)
        + (cweEntry?.guidance ? `\n\nSpecific guidance: ${cweEntry.guidance}` : "");

      const example = cweEntry?.example;
      const exampleBlock = example
        ? `\n\nExample:\nSnippet:\n${example.snippet}\n\nExpected JSON:\n${JSON.stringify({
            description: example.description,
            remediation: example.remediation,
            isFalsePositive: example.isFalsePositive,
            confidence: example.confidence
          })}`
        : "";

      const user = `${exampleBlock}\n\nNow analyze this snippet from ${filename}:\n${ruleResult.snippet}`;

      if (typeof this.session.setChatHistory === 'function') {
        this.session.setChatHistory([{ type: "system", text: system }]);
      }

      const responseText = await this.session.prompt(user, {
        grammar: this.grammar,
        maxTokens: 250
      });

      const parsed = this.grammar.parse(responseText) as EnrichedFinding;

      return {
        ...ruleResult,
        description: parsed.description,
        remediation: parsed.remediation,
        isFalsePositive: parsed.isFalsePositive,
        confidence: parsed.confidence
      };
    } catch (e) {
      console.warn('AI enrichment failed or timed out:', e);
      return fallback;
    }
  }
}

import rulesData from './data/security-rules.json';

export interface RuleResult {
  title: string;
  severity: 'high' | 'medium' | 'low' | 'critical';
  description: string;
  snippet: string;
  recommendation: string;
  cwe: string;
}

interface CompiledRule {
  id: string;
  cwe: string;
  owasp: string;
  languages: string[];
  severity: string;
  regex: RegExp;
  name: string;
  message: string;
}

// Compile regex rules on startup
const compiledRules: CompiledRule[] = rulesData.rules.map((r: any) => ({
  ...r,
  regex: new RegExp(r.pattern, r.flags || '')
}));

const EXTENSION_MAP: Record<string, string> = {
  '.js': 'javascript',
  '.jsx': 'javascript',
  '.ts': 'typescript',
  '.tsx': 'typescript',
  '.py': 'python',
  '.java': 'java',
  '.go': 'go',
  '.php': 'php',
  '.c': 'c',
  '.cpp': 'cpp',
  '.cs': 'csharp',
  '.html': 'html',
  '.vue': 'vue',
  '.sql': 'sql',
  '.sh': 'shell',
  '.json': 'json',
  '.yml': 'yaml',
  '.yaml': 'yaml',
  '.env': 'env'
};

export class SecurityRuleEngine {
  public static analyzeSnippet(code: string, extension: string): RuleResult[] {
    const results: RuleResult[] = [];
    const lines = code.split('\n');
    const language = EXTENSION_MAP[extension.toLowerCase()];

    if (!language) return results;

    const applicableRules = compiledRules.filter(r => r.languages.includes(language));
    if (applicableRules.length === 0) return results;

    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/*')) {
        return;
      }

      for (const rule of applicableRules) {
        if (rule.regex.test(line)) {
          // Context around the line
          const start = Math.max(0, index - 1);
          const end = Math.min(lines.length, index + 2);
          const snippet = lines.slice(start, end).join('\n');

          results.push({
            title: rule.name,
            severity: rule.severity as any,
            description: rule.message,
            snippet: snippet || line,
            recommendation: `Follow secure coding practices for ${rule.cwe} (${rule.owasp}).`,
            cwe: rule.cwe
          });
          break; // Matched one rule for this line
        }
      }
    });

    return results;
  }
}

import { contextBridge } from 'electron'
import { electronAPI } from '@electron-toolkit/preload'

// Custom APIs for renderer
const api = {}

// Use `contextBridge` APIs to expose Electron APIs to
// renderer only if context isolation is enabled, otherwise
// just add to the DOM global.
if (process.contextIsolated) {
  try {
    contextBridge.exposeInMainWorld('electron', electronAPI)
    contextBridge.exposeInMainWorld('api', api)
  } catch (error) {
    console.error(error)
  }
} else {
  // @ts-ignore (define in dts)
  window.electron = electronAPI
  // @ts-ignore (define in dts)
  window.api = api
}

import { ElectronAPI } from '@electron-toolkit/preload'

declare global {
  interface Window {
    electron: ElectronAPI
    api: unknown
  }
}
